from .manifest import parse_manifest
from .validator import validate_manifest

def load_and_validate(text):
    values = parse_manifest(text)
    validate_manifest(values)
    return values

def render_manifest(values):
    return chr(10).join(f"{key}={values[key]}" for key in sorted(values))
